defmodule JoobQ.BoundsTest do
  use ExUnit.Case, async: true

  alias JoobQ.{Batches, Job, RateLimits, Schedules, Workflows}

  # Text is bounded in code points, as the gateway counts: one grapheme of 100 000 combining marks is refused.
  @bomb "a" <> String.duplicate("́", 100_000)

  defp calls(text) do
    [
      fn -> RateLimits.body(text, 1, 1) end,
      fn -> Schedules.body(text, "q", "t", every: "1 hour") end,
      fn -> Workflows.start_body(text, nil, []) end,
      fn -> Job.body("q", text) end,
      fn -> Job.body(text, "t") end,
      fn -> Batches.body([{"q", "t"}], description: String.duplicate(text, 3)) end
    ]
  end

  test "text over its limit in code points is refused, however few graphemes it shows" do
    for text <- [@bomb, String.duplicate("x", 201)], call <- calls(text) do
      assert_raise ArgumentError, call
    end

    assert_raise ArgumentError, ~r/:queue/, fn -> Job.body(String.duplicate("q", 129), "t") end
    assert_raise ArgumentError, fn -> RateLimits.body(<<0xFF>>, 1, 1) end
  end

  test "200 code points of any script are taken" do
    text = String.duplicate("é", 200)
    assert %{"key" => ^text} = RateLimits.body(text, 1, 1)
    assert %{"name" => ^text} = Workflows.start_body(text, nil, [])
    assert %{"job_type" => ^text} = Job.body("q", text)
  end
end
